old:
// Live checkout: the price a customer pays, after the discount.
function roundPrice(amount) {
  return Math.round(amount * 100) / 100;
}

new:
// Live checkout: the price a customer pays, after the discount.
// Round half up on the decimal value: 1.005 * 100 is 100.49999999999999 in
// floating point, so scaling first and rounding would round it down. Fix the
// float error before rounding instead, matching how the ERP rounds.
function roundPrice(amount) {
  const scaled = Number((amount * 100).toFixed(10));
  return Math.round(scaled) / 100;
}
